// Some portions generated by Codex
package org.eclipse.rdf4j.query.parser.gql;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.query.MalformedQueryException;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class GqlExtendedExpressionTest {

	private SailRepository repository;
	private RepositoryConnection connection;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		connection = repository.getConnection();
	}

	@AfterEach
	void tearDown() {
		connection.close();
		repository.shutDown();
	}

	@Test
	void simpleCaseMatchesEveryPositionInTheOperandList() {
		for (int operand = 1; operand <= 3; operand++) {
			assertEquals("match", value("CASE " + operand
					+ " WHEN 1, 2, 3 THEN 'match' ELSE 'miss' END").stringValue());
		}
	}

	@Test
	void simpleCasePreservesWhenClausePriority() {
		assertEquals("first", value("CASE 2 WHEN 2, 3 THEN 'first' WHEN 1, 2 THEN 'later' END").stringValue());
		assertEquals("later", value("CASE 2 WHEN 3, 4 THEN 'first' WHEN 1, 2 THEN 'later' END").stringValue());
	}

	@Test
	void simpleCaseUsesElseOrNullWhenEveryOperandMisses() {
		assertEquals("miss", value("CASE 9 WHEN 1, 2, 3 THEN 'match' ELSE 'miss' END").stringValue());
		assertNull(value("CASE 9 WHEN 1, 2, 3 THEN 'match' END"));
	}

	@Test
	void nullOperandsDoNotHideALaterMatchingValue() {
		assertEquals("match", value("CASE 2 WHEN NULL, 1, 2 THEN 'match' ELSE 'miss' END").stringValue());
		assertEquals("miss", value("CASE NULL WHEN NULL, 1, 2 THEN 'match' ELSE 'miss' END").stringValue());
		assertEquals("null", value("CASE NULL WHEN NULL, IS NULL THEN 'null' ELSE 'miss' END").stringValue());
	}

	@Test
	void comparisonTailsUseTheCaseOperand() {
		for (String tail : new String[] { "= 2", "<> 3", "!= 3", "< 3", "<= 2", "> 1", ">= 2" }) {
			assertEquals("match", value("CASE 2 WHEN " + tail + " THEN 'match' ELSE 'miss' END").stringValue(), tail);
		}
		assertEquals("later", value("CASE 2 WHEN < 1, > 3 THEN 'miss' WHEN >= 2 THEN 'later' END").stringValue());
	}

	@Test
	void nullPredicateTailsAlwaysProduceABoolean() {
		assertEquals("null", value("CASE NULL WHEN IS NULL THEN 'null' ELSE 'miss' END").stringValue());
		assertEquals("present", value("CASE 2 WHEN IS NOT NULL THEN 'present' ELSE 'miss' END").stringValue());
		assertEquals("miss", value("CASE NULL WHEN IS NOT NULL THEN 'present' ELSE 'miss' END").stringValue());
	}

	@Test
	void truthPredicateTailsReuseTheExistingBooleanProfile() {
		assertEquals("true", value("CASE TRUE WHEN IS TRUE THEN 'true' ELSE 'miss' END").stringValue());
		assertEquals("false", value("CASE FALSE WHEN IS FALSE THEN 'false' ELSE 'miss' END").stringValue());
		assertEquals("unknown", value("CASE NULL WHEN IS UNKNOWN THEN 'unknown' ELSE 'miss' END").stringValue());
		assertEquals("not true", value("CASE NULL WHEN IS NOT TRUE THEN 'not true' ELSE 'miss' END").stringValue());
		assertEquals("not false", value("CASE TRUE WHEN IS NOT FALSE THEN 'not false' ELSE 'miss' END").stringValue());
	}

	@Test
	void membershipAndBetweenTailsReuseExistingProfilePredicates() {
		assertEquals("match", value("CASE 2 WHEN IN [1, 2, NULL] THEN 'match' ELSE 'miss' END").stringValue());
		assertEquals("match", value("CASE 2 WHEN BETWEEN 1 AND 2 THEN 'match' ELSE 'miss' END").stringValue());
		assertEquals("match", value("CASE 2 WHEN NOT IN [3, 4] THEN 'match' ELSE 'miss' END").stringValue());
		assertEquals("match", value("CASE 2 WHEN NOT BETWEEN 3 AND 4 THEN 'match' ELSE 'miss' END").stringValue());
		assertEquals("miss", value("CASE 2 WHEN NOT BETWEEN 1 AND 3 THEN 'match' ELSE 'miss' END").stringValue());
		assertEquals("later", value("CASE 2 WHEN IN [1, NULL] THEN 'miss' WHEN 2 THEN 'later' END").stringValue());
	}

	@Test
	void mixedTailsAndValuesShareOneWhenClause() {
		assertEquals("match", value("CASE 5 WHEN < 0, 2, BETWEEN 4 AND 6 THEN 'match' ELSE 'miss' END").stringValue());
		assertEquals("match", value("CASE 5 WHEN NULL, IS NULL, IN [4, 5] THEN 'match' ELSE 'miss' END").stringValue());
	}

	@Test
	void aLeadingNotRemainsAValueOperandUnlessItIntroducesAPredicateTail() {
		assertEquals("match", value("CASE FALSE WHEN NOT TRUE THEN 'match' ELSE 'miss' END").stringValue());
		assertEquals("match", value("CASE TRUE WHEN NOT FALSE AND TRUE THEN 'match' ELSE 'miss' END").stringValue());
		assertEquals("match", value("CASE FALSE WHEN TRUE, NOT TRUE THEN 'match' ELSE 'miss' END").stringValue());
	}

	@Test
	void quotedPredicateWordsAndOperatorsRemainValueOperands() {
		for (String operand : new String[] { "=", "<", "IS", "NOT", "IN", "BETWEEN" }) {
			assertEquals("match", value("CASE '" + operand + "' WHEN 'other', '" + operand
					+ "' THEN 'match' ELSE 'miss' END").stringValue(), operand);
		}
	}

	@Test
	void nestedCasesKeepTheirOwnOperandListsAndBranches() {
		assertEquals("nested", value("CASE CASE 1 WHEN 0, 1 THEN 2 ELSE 3 END "
				+ "WHEN 1, 2 THEN CASE 'a' WHEN 'b', 'a' THEN 'nested' ELSE 'miss' END ELSE 'miss' END")
						.stringValue());
		assertEquals("nested", value("CASE 2 WHEN = CASE 1 WHEN 0, 1 THEN 2 END "
				+ "THEN 'nested' ELSE 'miss' END").stringValue());
	}

	@Test
	void runtimeConditionsEvaluateOnlyTheSelectedResultBranch() {
		TupleQuery query = query("CASE $input WHEN 1, 2 THEN 7 WHEN 3 THEN 1 / $zero ELSE 9 END");
		query.setBinding("zero", connection.getValueFactory().createLiteral(0));
		for (int input : new int[] { 1, 2, 4 }) {
			query.setBinding("input", connection.getValueFactory().createLiteral(input));
			assertEquals(input == 4 ? "9" : "7", value(query).stringValue());
		}
	}

	@Test
	void unknownRuntimeOperandsCanBeFollowedByAMatch() {
		TupleQuery query = query("CASE $input WHEN 1 / $zero, 2 THEN 'match' ELSE 'miss' END");
		query.setBinding("input", connection.getValueFactory().createLiteral(2));
		query.setBinding("zero", connection.getValueFactory().createLiteral(0));
		assertEquals("match", value(query).stringValue());
	}

	@Test
	void searchedCaseStillUsesBooleanConditionsAndLazyResults() {
		TupleQuery query = query("CASE WHEN $input IS NULL THEN 'null' WHEN $input = 2 "
				+ "THEN 'two' ELSE 1 / $zero END");
		query.setBinding("zero", connection.getValueFactory().createLiteral(0));
		assertEquals("null", value(query).stringValue());
		query.setBinding("input", connection.getValueFactory().createLiteral(2));
		assertEquals("two", value(query).stringValue());
	}

	@Test
	void malformedOperandListsAndUnsupportedTailsAreRejected() {
		for (String expression : new String[] {
				"CASE 1 WHEN THEN 2 END", "CASE 1 WHEN , 1 THEN 2 END", "CASE 1 WHEN 1, THEN 2 END",
				"CASE WHEN TRUE, FALSE THEN 2 END", "CASE 1 WHEN IS TYPED INT THEN 2 END",
				"CASE 1 WHEN IS DIRECTED THEN 2 END", "CASE 1 WHEN IS LABELED A THEN 2 END",
				"CASE 1 WHEN IS SOURCE OF e THEN 2 END", "CASE 1 WHEN IS DESTINATION OF e THEN 2 END" }) {
			assertThrows(MalformedQueryException.class, () -> query(expression), expression);
		}
	}

	@Test
	void nestedExtendedCasesRespectExpressionBudgets() {
		String expression = "CASE 1 WHEN 0, 1 THEN ".repeat(200) + "1" + " END".repeat(200);
		MalformedQueryException failure = assertThrows(MalformedQueryException.class, () -> query(expression));
		assertTrue(failure.getMessage().contains("Expression "), failure.getMessage());
		assertTrue(failure.getMessage().contains("exceeds"), failure.getMessage());
	}

	@Test
	void nestedComparisonTailsRespectExpressionBudgets() {
		String expression = "CASE 1 WHEN = ".repeat(200) + "1" + " THEN 1 END".repeat(200);
		MalformedQueryException failure = assertThrows(MalformedQueryException.class, () -> query(expression));
		assertTrue(failure.getMessage().contains("Expression "), failure.getMessage());
		assertTrue(failure.getMessage().contains("exceeds"), failure.getMessage());
	}

	@Test
	void everyOperandCopyCountsAgainstTheComplexityBudget() {
		String expression = "CASE COALESCE(" + "NULL, ".repeat(64) + "1) WHEN "
				+ "0, ".repeat(64) + "1 THEN 2 END";
		MalformedQueryException failure = assertThrows(MalformedQueryException.class, () -> query(expression));
		assertTrue(failure.getMessage().contains("complexity exceeds"), failure.getMessage());
	}

	@Test
	void aLongOperandListFailsBeforeConstructingAnUnsafeAlgebraTree() {
		String expression = "CASE 1 WHEN " + "0, ".repeat(2_000) + "1 THEN 2 END";
		MalformedQueryException failure = assertThrows(MalformedQueryException.class, () -> query(expression));
		assertTrue(failure.getMessage().contains("complexity exceeds"), failure.getMessage());
	}

	private TupleQuery query(String expression) {
		return connection.prepareTupleQuery(QueryLanguage.GQL, "RETURN " + expression + " AS value");
	}

	private Value value(String expression) {
		return value(query(expression));
	}

	private Value value(TupleQuery query) {
		try (TupleQueryResult result = query.evaluate()) {
			assertTrue(result.hasNext());
			Value value = result.next().getValue("value");
			assertFalse(result.hasNext());
			return value;
		}
	}
}
